const incoming = $input.first().json;
const body = incoming.body ?? incoming;

function flatten(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value.trim();

  if (Array.isArray(value)) {
    return value
      .map((entry, index) => {
        if (typeof entry === 'string') return `${index + 1}. ${entry}`;
        if (entry == null) return '';

        const parts = [
          entry.gap,
          entry.research_gap,
          entry.researchGap,
          entry.description,
          entry.statement,
          entry.text,
          entry.title
        ].filter(Boolean);

        return parts.length ? `${index + 1}. ${parts.join(' - ')}` : JSON.stringify(entry);
      })
      .filter(Boolean)
      .join('\n');
  }

  if (typeof value === 'object') {
    const parts = [
      value.title,
      value.rationale,
      value.gap,
      value.gaps,
      value.researchGap,
      value.research_gap,
      value.description,
      value.statement,
      value.text
    ].filter(Boolean);

    return parts.length ? parts.map(flatten).join('\n') : JSON.stringify(value);
  }

  return String(value).trim();
}

const baselineSource =
  body.baseline ??
  body.researchBaseline ??
  body.semanticBaseline ??
  body.catalystBaseline ??
  body.catalyst_baseline ??
  {};

const title = flatten(
  baselineSource.title ??
  baselineSource.researchTitle ??
  baselineSource.research_title ??
  body.title ??
  body.researchTitle
);

const rationale = flatten(
  baselineSource.rationale ??
  baselineSource.researchRationale ??
  baselineSource.research_rationale ??
  body.rationale
);

const gaps = flatten(
  baselineSource.gaps ??
  baselineSource.gap ??
  baselineSource.researchGaps ??
  baselineSource.research_gaps ??
  baselineSource.researchGap ??
  baselineSource.research_gap ??
  body.gaps ??
  body.gap
);

const rawText = String(
  body.extracted_text ??
  body.extractedText ??
  body.text ??
  body.documentText ??
  body.document_text ??
  body.body?.extracted_text ??
  body.body?.text ??
  ''
).trim();

if (!rawText) {
  throw new Error('No extracted text found. Expected extracted_text, extractedText, text, documentText, or document_text.');
}

if (!title && !rationale && !gaps) {
  throw new Error('No research baseline found. Expected body.baseline with title/rationale/gaps or equivalent fields.');
}

return [{
  json: {
    baseline: {
      title,
      rationale,
      gaps
    },
    raw_extracted_text: rawText,
    meta: {
      documentId: body.documentId ?? body.document_id ?? body.id ?? null,
      filename: body.filename ?? body.fileName ?? body.file_name ?? null,
      source: 'citewise-n8n-semantic-evaluator'
    }
  }
}];

const item = $input.first().json;

const baseline = item.baseline ?? {};
const rawText = String(item.raw_extracted_text ?? '').trim();

function normalize(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const stopwords = new Set([
  'about', 'above', 'after', 'again', 'against', 'among', 'based', 'because',
  'before', 'being', 'below', 'between', 'could', 'during', 'early', 'field',
  'first', 'found', 'from', 'have', 'having', 'into', 'more', 'most', 'other',
  'paper', 'research', 'result', 'results', 'should', 'study', 'studies',
  'system', 'than', 'their', 'there', 'these', 'this', 'those', 'through',
  'using', 'where', 'which', 'while', 'within', 'with', 'would'
]);

const baselineText = [baseline.title, baseline.rationale, baseline.gaps]
  .filter(Boolean)
  .join(' ');

const keywords = [...new Set(
  normalize(baselineText)
    .split(/\s+/)
    .filter(w => w.length >= 5 && !stopwords.has(w))
)].slice(0, 80);

function splitToCandidateChunks(text) {
  let chunks = text
    .split(/\n\s*\n+/)
    .map(p => p.trim())
    .filter(p => p.length >= 120);

  // PDF extraction sometimes has weak paragraph breaks. Fall back to sliding chunks.
  if (chunks.length < 8) {
    chunks = [];
    const size = 1400;
    const overlap = 180;
    for (let i = 0; i < text.length; i += (size - overlap)) {
      const part = text.slice(i, i + size).trim();
      if (part.length >= 120) chunks.push(part);
    }
  }

  return chunks;
}

const candidates = splitToCandidateChunks(rawText);

function chunkScore(chunk, index) {
  const lower = normalize(chunk);
  const keywordHits = keywords.filter(k => lower.includes(k)).length;

  const academicSignal =
    /\b(abstract|introduction|methodology|method|framework|model|experiment|evaluation|findings|results|discussion|conclusion)\b/i.test(chunk)
      ? 2
      : 0;

  const citationSignal =
    /\b(doi|references|journal|conference|proceedings|et al\.|volume|issue)\b/i.test(chunk)
      ? 1
      : 0;

  // Keep a little preference for early chunks because abstracts/intros are usually there.
  const earlySignal = index < 8 ? 1 : 0;

  return keywordHits * 5 + academicSignal + citationSignal + earlySignal;
}

const ranked = candidates
  .map((chunk, index) => ({
    chunk,
    index,
    score: chunkScore(chunk, index)
  }))
  .sort((a, b) => b.score - a.score || a.index - b.index);

// Select top-scoring chunks, but preserve original document order for readability.
let selected = ranked
  .slice(0, 14)
  .sort((a, b) => a.index - b.index);

if (!selected.length) {
  selected = candidates.slice(0, 8).map((chunk, index) => ({ chunk, index, score: 0 }));
}

let finalText = selected
  .map((x, i) => `[CHUNK ${i + 1} | original_order=${x.index + 1} | relevance_hint=${x.score}]\n${x.chunk}`)
  .join('\n\n---CHUNK BREAK---\n\n');

// Keep request size manageable for <=15s scoring.
const MAX_CHARS = 30000;
if (finalText.length > MAX_CHARS) {
  finalText = finalText.slice(0, MAX_CHARS);
}

return [{
  json: {
    baseline,
    extracted_text: finalText,
    raw_extracted_text: rawText,
    meta: item.meta ?? {},
    chunkStats: {
      rawCharacters: rawText.length,
      candidateChunks: candidates.length,
      selectedChunks: selected.length,
      selectedCharacters: finalText.length,
      keywordCount: keywords.length
    }
  }
}];

const item = $input.first().json;

let raw =
  item.output ??
  item.text ??
  item.response ??
  item.message?.content ??
  item.content;

if (raw == null) {
  throw new Error('No AI Agent text found. Keys on item: ' + Object.keys(item).join(', '));
}

raw = String(raw)
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// If the model accidentally includes text before/after JSON, recover the JSON object.
const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
  throw new Error('AI Agent did not return a JSON object. Raw output: ' + raw.slice(0, 500));
}

let parsed;
try {
  parsed = JSON.parse(raw.slice(firstBrace, lastBrace + 1));
} catch (error) {
  throw new Error('AI Agent returned invalid JSON. Parse error: ' + error.message + '. Raw output: ' + raw.slice(0, 500));
}

const validationFlags = [];

function clampScore(value, fieldName) {
  const n = Number(value);
  if (!Number.isFinite(n)) {
    validationFlags.push(`${fieldName} missing or invalid; defaulted to 0`);
    return 0;
  }

  const rounded = Math.round(n);
  if (rounded < 0 || rounded > 100) {
    validationFlags.push(`${fieldName} was outside 0-100 and was clamped`);
  }

  return Math.max(0, Math.min(100, rounded));
}

function cleanStringArray(value, fieldName, maxItems = 8) {
  if (!Array.isArray(value)) {
    validationFlags.push(`${fieldName} missing or invalid; defaulted to []`);
    return [];
  }

  return value
    .map(v => String(v ?? '').trim())
    .filter(Boolean)
    .slice(0, maxItems);
}

const allowedConfidence = ['High', 'Medium', 'Low'];
let confidenceLevel = String(parsed.confidenceLevel ?? '').trim();
if (!allowedConfidence.includes(confidenceLevel)) {
  validationFlags.push('confidenceLevel missing or invalid; defaulted to Low');
  confidenceLevel = 'Low';
}

const allowedCriteria = ['Gap Alignment', 'Methodology', 'Theory', 'Citation Quality'];
const allowedRelevance = ['High', 'Medium', 'Low'];
const allowedEvidenceTypes = ['supporting', 'weakness', 'mismatch'];

const evidence = Array.isArray(parsed.evidenceExcerpts)
  ? parsed.evidenceExcerpts
      .map((e, index) => {
        const criterion = allowedCriteria.includes(String(e.criterion))
          ? String(e.criterion)
          : 'Gap Alignment';

        if (!allowedCriteria.includes(String(e.criterion))) {
          validationFlags.push(`evidenceExcerpts[${index}].criterion invalid; defaulted to Gap Alignment`);
        }

        const relevanceLevel = allowedRelevance.includes(String(e.relevanceLevel))
          ? String(e.relevanceLevel)
          : 'Low';

        if (!allowedRelevance.includes(String(e.relevanceLevel))) {
          validationFlags.push(`evidenceExcerpts[${index}].relevanceLevel invalid; defaulted to Low`);
        }

        const evidenceType = allowedEvidenceTypes.includes(String(e.evidenceType))
          ? String(e.evidenceType)
          : 'supporting';

        if (!allowedEvidenceTypes.includes(String(e.evidenceType))) {
          validationFlags.push(`evidenceExcerpts[${index}].evidenceType invalid; defaulted to supporting`);
        }

        return {
          criterion,
          quoteText: String(e.quoteText ?? '').trim(),
          pageNumber: Number.isFinite(Number(e.pageNumber)) ? Number(e.pageNumber) : 1,
          relevanceLevel,
          evidenceType
        };
      })
      .filter(e => e.quoteText.length > 0)
      .slice(0, 5)
  : [];

if (!Array.isArray(parsed.evidenceExcerpts)) {
  validationFlags.push('evidenceExcerpts missing or invalid; defaulted to []');
}

return [{
  json: {
    gapAlignmentScore: clampScore(parsed.gapAlignmentScore, 'gapAlignmentScore'),
    methodologyScore: clampScore(parsed.methodologyScore, 'methodologyScore'),
    theoreticalScore: clampScore(parsed.theoreticalScore, 'theoreticalScore'),
    citationScore: clampScore(parsed.citationScore, 'citationScore'),
    confidenceLevel,
    mismatchFlags: cleanStringArray(parsed.mismatchFlags, 'mismatchFlags'),
    weaknessFlags: cleanStringArray(parsed.weaknessFlags, 'weaknessFlags'),
    evidenceExcerpts: evidence,
    validationFlags,
    rawAiResponse: raw.slice(firstBrace, lastBrace + 1)
  }
}];

const ai = $input.first().json;

// In n8n Code nodes, this fetches data from a previous node by name.
// If your n8n version complains, replace .first().json with .item.json.
const source = $('Select Relevant Text Chunks').first().json;

const rawText = String(source.raw_extracted_text ?? source.extracted_text ?? '');
const baseline = source.baseline ?? {};
const meta = source.meta ?? {};

const WEIGHTS = {
  gap: 0.40,
  methodology: 0.25,
  theory: 0.20,
  citation: 0.15
};

const THRESHOLDS = {
  recommendedOverall: 80,
  recommendedGapMinimum: 75,
  needsReviewOverall: 60,
  lowGapMaximum: 40
};

function clamp(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(100, Math.round(n)));
}

function normalize(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function looseContains(text, quote) {
  const q = normalize(quote);
  if (q.length < 20) return false;
  return normalize(text).includes(q);
}

function uniqStrings(values, maxItems = 12) {
  return [...new Set(
    (Array.isArray(values) ? values : [])
      .map(v => String(v ?? '').trim())
      .filter(Boolean)
  )].slice(0, maxItems);
}

const stopwords = new Set([
  'about', 'above', 'after', 'again', 'against', 'among', 'based', 'because',
  'before', 'being', 'below', 'between', 'could', 'during', 'early', 'field',
  'first', 'found', 'from', 'have', 'having', 'into', 'more', 'most', 'other',
  'paper', 'research', 'result', 'results', 'should', 'study', 'studies',
  'system', 'than', 'their', 'there', 'these', 'this', 'those', 'through',
  'using', 'where', 'which', 'while', 'within', 'with', 'would'
]);

const baselineText = [
  baseline.title,
  baseline.rationale,
  baseline.gaps
].filter(Boolean).join(' ');

const baselineKeywords = [...new Set(
  normalize(baselineText)
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length >= 5 && !stopwords.has(w))
)].slice(0, 80);

function keywordHits(text) {
  const lower = normalize(text);
  return baselineKeywords.filter(k => lower.includes(k)).length;
}

const validationFlags = uniqStrings(ai.validationFlags ?? [], 20);

const originalEvidenceCount = Array.isArray(ai.evidenceExcerpts) ? ai.evidenceExcerpts.length : 0;

const verifiedEvidence = (Array.isArray(ai.evidenceExcerpts) ? ai.evidenceExcerpts : [])
  .map(e => ({
    criterion: ['Gap Alignment', 'Methodology', 'Theory', 'Citation Quality'].includes(String(e.criterion))
      ? String(e.criterion)
      : 'Gap Alignment',
    quoteText: String(e.quoteText ?? '').trim(),
    pageNumber: Number.isFinite(Number(e.pageNumber)) ? Number(e.pageNumber) : 1,
    relevanceLevel: ['High', 'Medium', 'Low'].includes(String(e.relevanceLevel))
      ? String(e.relevanceLevel)
      : 'Low',
    evidenceType: ['supporting', 'weakness', 'mismatch'].includes(String(e.evidenceType))
      ? String(e.evidenceType)
      : 'supporting'
  }))
  .filter(e => looseContains(rawText, e.quoteText))
  .slice(0, 5);

if (verifiedEvidence.length < originalEvidenceCount) {
  validationFlags.push('Some AI evidence excerpts were removed because they were not found in the extracted PDF text');
}

let gap = clamp(ai.gapAlignmentScore);
let methodology = clamp(ai.methodologyScore);
let theoretical = clamp(ai.theoreticalScore);
let citation = clamp(ai.citationScore);

let mismatchFlags = uniqStrings(ai.mismatchFlags ?? [], 12);
let weaknessFlags = uniqStrings(ai.weaknessFlags ?? [], 12);

const highEvidenceCount = verifiedEvidence.filter(e => e.relevanceLevel === 'High').length;
const mediumOrHighEvidenceCount = verifiedEvidence.filter(e => e.relevanceLevel === 'High' || e.relevanceLevel === 'Medium').length;
const evidenceText = verifiedEvidence.map(e => e.quoteText).join(' ');
const evidenceKeywordHits = keywordHits(evidenceText);

const hasGapEvidence = verifiedEvidence.some(e =>
  e.criterion === 'Gap Alignment' &&
  (e.relevanceLevel === 'High' || e.relevanceLevel === 'Medium') &&
  e.evidenceType !== 'mismatch'
);

const hasMethodEvidence = verifiedEvidence.some(e =>
  e.criterion === 'Methodology' &&
  e.evidenceType !== 'mismatch'
);

const hasTheoryEvidence = verifiedEvidence.some(e =>
  e.criterion === 'Theory' &&
  e.evidenceType !== 'mismatch'
);

// Hard evidence caps.
if (verifiedEvidence.length === 0) {
  gap = Math.min(gap, 40);
  methodology = Math.min(methodology, 45);
  theoretical = Math.min(theoretical, 45);
  weaknessFlags.push('No verified evidence excerpts were found in the extracted document text');
  validationFlags.push('Scores capped because no verified evidence excerpts were found');
}

if (!hasGapEvidence) {
  gap = Math.min(gap, 40);
  weaknessFlags.push('No verified evidence directly supports the research gap alignment');
  validationFlags.push('Gap score capped because no verified gap-alignment evidence was found');
}

if (mediumOrHighEvidenceCount === 0) {
  gap = Math.min(gap, 50);
  validationFlags.push('Gap score capped because all verified evidence was low relevance');
}

if (highEvidenceCount === 0) {
  gap = Math.min(gap, 60);
  validationFlags.push('Gap score capped because no high-relevance evidence was verified');
}

// If the evidence does not share meaningful baseline terms, prevent inflated gap scores.
if (evidenceKeywordHits === 0) {
  gap = Math.min(gap, 45);
  validationFlags.push('Gap score capped because verified evidence did not share meaningful baseline terms');
} else if (evidenceKeywordHits < 2) {
  gap = Math.min(gap, 60);
  validationFlags.push('Gap score capped because verified evidence had weak baseline keyword overlap');
}

if (!hasMethodEvidence) {
  methodology = Math.min(methodology, 60);
  weaknessFlags.push('No verified methodology evidence was found');
}

if (!hasTheoryEvidence) {
  theoretical = Math.min(theoretical, 60);
  weaknessFlags.push('No verified theory or framework evidence was found');
}

// Methods/theory should not outrank a weakly aligned document too much.
if (gap < 50) {
  methodology = Math.min(methodology, 60);
  theoretical = Math.min(theoretical, 60);
  validationFlags.push('Methodology and theory scores capped because gap alignment is weak');
}

// Citation score should be based on visible academic signals only.
const hasCitationSignals = /\b(doi|references|journal|conference|proceedings|volume|issue|publisher|issn|isbn|et al\.|abstract|keywords)\b/i.test(rawText);
if (!hasCitationSignals) {
  citation = Math.min(citation, 55);
  weaknessFlags.push('Limited visible citation or academic source traceability signals');
  validationFlags.push('Citation score capped because citation/source quality signals were limited');
}

// Detect critical mismatch from AI flags and verified mismatch evidence.
const mismatchText = [
  ...mismatchFlags,
  ...verifiedEvidence
    .filter(e => e.evidenceType === 'mismatch')
    .map(e => e.quoteText)
].join(' ');

const hasCriticalMismatch = /\b(critical|unrelated|not related|does not address|no connection|wrong population|different population|different domain|different field|different problem|outside scope)\b/i.test(mismatchText);

if (hasCriticalMismatch) {
  gap = Math.min(gap, 45);
  validationFlags.push('Gap score capped because a critical mismatch was detected');
}

const overallScore = Math.round(
  gap * WEIGHTS.gap +
  methodology * WEIGHTS.methodology +
  theoretical * WEIGHTS.theory +
  citation * WEIGHTS.citation
);

let confidenceLevel = ['High', 'Medium', 'Low'].includes(String(ai.confidenceLevel))
  ? String(ai.confidenceLevel)
  : 'Low';

function downgradeConfidence(current, target) {
  const rank = { High: 3, Medium: 2, Low: 1 };
  return rank[target] < rank[current] ? target : current;
}

if (verifiedEvidence.length === 0 || hasCriticalMismatch) {
  confidenceLevel = downgradeConfidence(confidenceLevel, 'Low');
} else if (validationFlags.length >= 3 || highEvidenceCount === 0 || evidenceKeywordHits < 2) {
  confidenceLevel = downgradeConfidence(confidenceLevel, 'Medium');
}

let recommendationStatus;

if (
  verifiedEvidence.length === 0 ||
  gap <= THRESHOLDS.lowGapMaximum ||
  overallScore < THRESHOLDS.needsReviewOverall ||
  hasCriticalMismatch
) {
  recommendationStatus = 'Low Relevance';
} else if (
  overallScore >= THRESHOLDS.recommendedOverall &&
  gap >= THRESHOLDS.recommendedGapMinimum &&
  confidenceLevel !== 'Low' &&
  !hasCriticalMismatch
) {
  recommendationStatus = 'Recommended';
} else {
  recommendationStatus = 'Needs Review';
}

const relevanceLevel =
  recommendationStatus === 'Recommended'
    ? 'High'
    : recommendationStatus === 'Needs Review'
      ? 'Medium'
      : 'Low';

// Final schema compatible with CiteWise backend expectations.
return [{
  json: {
    documentId: meta.documentId ?? null,
    filename: meta.filename ?? null,
    scores: {
      gapAlignment: Math.round(gap),
      methodology: Math.round(methodology),
      theory: Math.round(theoretical),
      citationQuality: Math.round(citation)
    },
    gapAlignmentScore: Math.round(gap),
    methodologyScore: Math.round(methodology),
    theoreticalScore: Math.round(theoretical),
    citationScore: Math.round(citation),
    overallScore,
    recommendationStatus,
    confidenceLevel,
    relevanceLevel,
    mismatchFlags: uniqStrings(mismatchFlags, 12),
    weaknessFlags: uniqStrings(weaknessFlags, 12),
    validationFlags: uniqStrings(validationFlags, 20),
    evidenceExcerpts: verifiedEvidence.map((e, index) => ({
      criterion: e.criterion,
      quoteText: e.quoteText,
      pageNumber: e.pageNumber,
      relevanceLevel: e.relevanceLevel,
      evidenceType: e.evidenceType,
      displayOrder: index + 1
    })),
    rawAiResponse: ai.rawAiResponse ?? null,
    scoringModel: {
      weights: WEIGHTS,
      thresholds: THRESHOLDS,
      note: 'Provisional configurable demo rules. Replace with teacher-approved rubric/manual thresholds when provided.'
    }
  }
}];
